import{_ as a,o as i,c as s,ae as t}from"./chunks/framework.C4zpkcTP.js";const g=JSON.parse('{"title":"Installation","description":"Install Laravel New Relic, set your license key and switch your log channel to newrelic.","frontmatter":{"title":"Installation","description":"Install Laravel New Relic, set your license key and switch your log channel to newrelic."},"headers":[],"relativePath":"laravel-newrelic/installation.md","filePath":"laravel-newrelic/installation.md"}'),n={name:"laravel-newrelic/installation.md"};function l(o,e,r,c,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-newrelic</span></span></code></pre></div><p>The service provider is auto-discovered and registers a <code>newrelic</code> log channel. Point your logs at it and give it a license (ingest) key:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LOG_CHANNEL=newrelic</span></span>
<span class="line"><span>NEW_RELIC_LICENSE_KEY=your-ingest-license-key</span></span></code></pre></div><p><code>NEW_RELIC_API_KEY</code> is still accepted when <code>NEW_RELIC_LICENSE_KEY</code> is not set. When neither is set, the New Relic PHP agent&#39;s <code>newrelic.license</code> INI value is used.</p><p>Publish the config file (optional):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;newrelic-config&quot;</span></span></code></pre></div><p>This writes <code>config/newrelic.php</code>. The <code>newrelic</code> tag publishes the same file.</p><h2 id="new-relic-php-agent" tabindex="-1">New Relic PHP agent <a class="header-anchor" href="#new-relic-php-agent" aria-label="Permalink to &quot;New Relic PHP agent&quot;">​</a></h2><p>The <a href="https://docs.newrelic.com/docs/apm/agents/php-agent/getting-started/introduction-new-relic-php/" target="_blank" rel="noreferrer">New Relic PHP agent</a> is optional. Without it, logs are still shipped to New Relic Logs. With it, logs are linked to their APM transaction (logs in context) and Octane requests are reported as separate, route-named transactions. The agent reports queue jobs as their own transactions by itself.</p>`,10)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
